<template>
  <div class="page fade-up">
    <router-link :to="`/projects/${pid}`" class="back">← 返回项目</router-link>
    <div class="head"><div><h1>{{character?.name || '角色'}} · 新形象与服装</h1><p class="sub">所有新形象都绑定当前角色，并以该角色标准像锁定身份后换装；不会创建无归属套装。</p></div><div class="head-actions"><button class="btn" :disabled="!character?.portrait" @click="openDesign">✨ 基于标准像设计新形象</button><button v-if="mode!=='motion'" class="btn btn-secondary" @click="mode==='assets'?openLook():mode==='stages'?openStage():openOutfit()">＋ {{mode==='assets'?'手工新建单件资产':mode==='stages'?'新建年龄阶段':'手工组合套装'}}</button></div></div>
    <div class="card character-anchor"><img v-if="character?.portrait" :src="img(character.portrait)" alt="角色标准像" title="点击查看大图" @click="openViewer(character.portrait, `${character.name} · 标准像`)"><div v-else class="anchor-empty">暂无标准像</div><div><strong>身份锚点：{{character?.name || '加载中…'}}</strong><span v-if="character?.portrait">生成新形象时，Picture 1 固定使用这张标准像，锁定同一张脸和项目画风。</span><span v-else class="error-text">请先返回项目，为该角色生成或上传标准像；没有标准像不能提交换装设计。</span></div></div>
    <div class="card workflow-tip"><strong>推荐流程</strong><span>① 独立资产中新建服装/鞋履/发型/配饰并审核、生成参考图</span><span>② 完整套装中组合这些资产并审核</span><span>③ 生成套装图和四视图</span><span>④ 在场景编辑的“本场角色造型套装”中选择使用</span></div>
    <div class="mode-tabs"><button class="btn btn-sm" :class="mode==='outfits'?'':'btn-ghost'" @click="mode='outfits'">完整套装（{{outfits.length}}）</button><button class="btn btn-sm" :class="mode==='assets'?'':'btn-ghost'" @click="mode='assets'">独立资产（{{looks.length}}）</button><button class="btn btn-sm" :class="mode==='stages'?'':'btn-ghost'" @click="mode='stages'">年龄阶段（{{stages.length}}）</button><button class="btn btn-sm" :class="mode==='motion'?'':'btn-ghost'" @click="mode='motion'">动态参考（{{motions.length}}）</button></div>
    <div v-if="error" class="notice error-notice">{{error}}</div>

    <template v-if="mode==='assets'">
      <div class="category-tabs"><button v-for="(v,k) in labels" :key="k" class="btn btn-sm" :class="activeCategory===k?'':'btn-ghost'" @click="activeCategory=k">{{v}}（{{looks.filter(x=>x.category===k).length}}）</button></div>
      <div class="look-grid"><article v-for="x in filteredLooks" :key="x.id" class="card look">
        <img v-if="x.image" :src="img(x.image)" :alt="x.name" title="点击查看大图" @click="openViewer(x.image, `${x.name} · 造型资产`)"><div v-else class="empty-img">{{x.image_task_id?'H3 生成中…':'暂无参考图'}}</div>
        <header><h3>{{x.name}}</h3><span class="badge">{{labels[x.category]||x.category}}</span></header><p>{{x.description||'暂无描述'}}</p>
        <small>{{x.audit_status}} · 优先级 {{x.priority}}</small><p v-if="x.image_error" class="error-text">{{x.image_error}}</p>
        <div class="actions"><button class="btn btn-sm btn-ghost" @click="openLook(x)">编辑</button><button class="btn btn-sm btn-secondary" @click="derive(x)">以此新建</button><button class="btn btn-sm btn-ghost" @click="actLook(x,'expand')">AI扩写</button><button class="btn btn-sm btn-secondary" @click="actLook(x,'approve')">审核通过</button><button class="btn btn-sm" :disabled="x.image_task_id || (x.audit_status!=='approved'&&x.audit_status!=='published')" @click="actLook(x,'image')">{{x.image_task_id?'生成中…':'生成参考图'}}</button><label class="btn btn-sm btn-ghost">上传图<input hidden type="file" accept="image/*" @change="upload(x,$event)"></label><button class="btn btn-sm btn-danger" @click="removeLook(x)">删除</button></div>
      </article></div>
    </template>

    <template v-else-if="mode==='stages'">
      <div class="card workflow-tip"><strong>年龄阶段</strong><span>① 新建阶段并填写该年龄的外貌</span><span>② 审阅提示词后以主标准像为参考，直接生成该年龄的四视图（含正面面部特写）</span><span>③ 审核通过后，在完整套装中把套装挂到该阶段</span><span>④ 在套装卡上“按集指定”批量用于第 N–M 集</span></div>
      <div v-if="!stages.length" class="card stage-empty">暂无年龄阶段。角色主档案与主标准像代表默认年龄；只有剧情跨越不同年龄（如童年回忆）时才需要新建阶段。</div>
      <div class="look-grid"><article v-for="s in stages" :key="s.id" class="card look">
        <img v-if="s.portrait" :src="img(s.portrait)" :alt="ageStageLabel(s)" title="点击查看大图" @click="openViewer(s.portrait, `${character?.name} · ${ageStageLabel(s)} · 阶段四视图`)"><div v-else class="empty-img">{{s.portrait_task_id?'阶段四视图生成中…':'暂无阶段四视图'}}</div>
        <header><h3>{{ageStageLabel(s)}}</h3><span class="badge">{{s.audit_status}}</span></header><p>{{s.appearance||'暂无外貌描述'}}</p>
        <small>四视图引擎：{{stageEngineLabel(s.portrait_engine)}} · 已挂套装 {{outfits.filter(o=>o.age_stage_id===s.id).length}} 套</small><p v-if="s.portrait_error" class="error-text">{{s.portrait_error}}</p><div v-if="stageHistory(s).length" class="stage-history"><span>历史四视图（保留，可恢复）</span><figure v-for="f in stageHistory(s)" :key="f"><img :src="img(f)" :alt="`${ageStageLabel(s)}历史四视图`" title="点击查看大图" @click="openViewer(f, `${character?.name} · ${ageStageLabel(s)} · 历史四视图`)"><button class="btn btn-xs btn-ghost" :disabled="!!s.portrait_task_id" @click="restoreStagePortrait(s,f)">恢复</button></figure></div>
        <div class="actions"><button class="btn btn-sm btn-ghost" @click="openStage(s)">编辑</button><button class="btn btn-sm" :disabled="!!s.portrait_task_id||!character?.portrait" :title="character?.portrait?'':'请先为角色生成或上传主标准像；也可直接上传阶段四视图'" @click="openStagePrompt(s)">{{s.portrait_task_id?'生成中…':'审阅提示词并生成四视图'}}</button><label class="btn btn-sm btn-ghost">上传四视图<input hidden type="file" accept="image/*" @change="uploadStage(s,$event)"></label><button class="btn btn-sm btn-secondary" :disabled="!s.portrait" @click="approveStage(s)">审核通过</button><button class="btn btn-sm btn-secondary" :disabled="!character?.portrait" @click="openDesign(s)">为此阶段设计套装</button><button class="btn btn-sm btn-danger" @click="removeStage(s)">删除</button></div>
      </article></div>
    </template>

    <div v-else-if="mode==='outfits'" class="outfit-grid"><article v-for="o in outfits" :key="o.id" class="card outfit">
      <div v-if="o.age_stage" class="outfit-binding"><img v-if="o.age_stage.portrait" :src="img(o.age_stage.portrait)" title="点击查看阶段四视图" @click="openViewer(o.age_stage.portrait, `${character?.name} · ${ageStageLabel(o.age_stage)} · 阶段四视像`)"><span>绑定角色：<strong>{{character?.name}}</strong> · 年龄阶段：<strong>{{ageStageLabel(o.age_stage)}}</strong><br>身份参考：该阶段标准像（不使用成人四视图）<template v-if="!stageApproved(o.age_stage)"> · 阶段未审核</template></span></div>
      <div v-else class="outfit-binding"><img v-if="character?.portrait" :src="img(character.portrait)" title="点击查看角色标准像" @click="openViewer(character.portrait, `${character.name} · 标准像`)"><span>绑定角色：<strong>{{character?.name}}</strong><br>身份参考：当前角色标准像（Picture 1）</span></div><div class="outfit-media"><img v-if="o.image" :src="img(o.image)" :alt="`${o.name}换装定妆照`" title="点击查看大图" @click="openViewer(o.image, `${o.name} · 换装定妆照`)"><div v-else class="empty-img">{{o.image_task_id?`${imageEngineLabel(o.image_engine)} 生成换装定妆照中…`:'待生成换装定妆照'}}</div><img v-if="o.sheet" :src="img(o.sheet)" :alt="`${o.name}四视图`" title="点击查看大图" @click="openViewer(o.sheet, `${o.name} · 四视图`)"><div v-else class="empty-img">{{o.sheet_task_id?'Krea2 生成四视图中…':'暂无 Krea2 四视图'}}</div></div>
      <header><h3>{{o.name}}</h3><span class="badge">{{imageEngineLabel(o.image_engine)}}</span><span class="badge">{{o.audit_status}}</span></header><p>{{o.description||'暂无套装说明'}}</p>
      <div class="chips"><span v-for="i in o.items" :key="i.id" class="chip">{{labels[i.look?.category]}} · {{i.look?.name}}</span></div>
      <p v-if="o.image_error||o.sheet_error" class="error-text">{{o.image_error||o.sheet_error}}</p>
      <div class="actions"><button class="btn btn-sm btn-ghost" @click="openOutfit(o)">编辑组合</button><button class="btn btn-sm btn-secondary" @click="outfitAct(o,'approve')">审核通过</button><button class="btn btn-sm" :disabled="o.image_task_id||!approved(o)||!character?.portrait||stageBlocked(o)" :title="stageBlocked(o)?'请先为该年龄阶段生成标准像并审核通过':''" @click="outfitAct(o,'image')">{{o.image_task_id?'生成中…':`用 ${imageEngineLabel(o.image_engine)} 生成换装图`}}</button><label class="btn btn-sm btn-ghost">手工替换换装图<input hidden type="file" accept="image/*" @change="uploadOutfit(o,$event,false)"></label><button class="btn btn-sm" :disabled="o.sheet_task_id||!o.image||!approved(o)" @click="outfitAct(o,'sheet')">{{o.sheet_task_id?'Krea2 生成中…':'用换装照生成 Krea2 四视图'}}</button><label class="btn btn-sm btn-ghost">上传四视图<input hidden type="file" accept="image/*" @change="uploadOutfit(o,$event,true)"></label><button class="btn btn-sm btn-secondary" :disabled="!approved(o)||stageBlocked(o)" title="按集数范围批量指定给该角色可见的 Scene" @click="openEpisodeAssign(o)">按集指定</button><button class="btn btn-sm btn-ghost" title="生成或上传替换下来的旧定妆照/四视图都保留在这里，可恢复" @click="openOutfitHistory(o)">历史版本</button><button class="btn btn-sm btn-danger" @click="removeOutfit(o)">删除</button></div>
    </article></div>

    <section v-else class="card motion-panel"><h2>角色动态参考视频</h2><p class="sub">用于保存可复用的走路、转身、表情或口型参考；不会自动占用H3静态参考图名额。</p><form class="motion-upload" @submit.prevent="uploadMotion"><label>名称<input v-model="motionName" class="input" placeholder="例如：自然走路节奏"></label><label>视频<input ref="motionVideo" type="file" accept="video/mp4,video/webm,video/quicktime" required></label><label>可选音频<input ref="motionAudio" type="file" accept="audio/*"></label><button class="btn" :disabled="motionUploading">{{motionUploading?'上传中…':'上传动态参考'}}</button></form><article v-for="m in motions" :key="m.id" class="motion-row"><video :src="fileURL(m.video_path)" controls preload="metadata"></video><div><strong>{{m.name}}</strong><p>{{m.selected?'当前选中':'可用参考'}}<span v-if="m.audio_path"> · 含音频</span></p></div><button class="btn btn-sm btn-secondary" :disabled="m.selected" @click="selectMotion(m)">设为当前</button><button class="btn btn-sm btn-danger" @click="deleteMotion(m)">删除</button></article></section>

    <Teleport to="body"><div v-if="viewer" class="look-viewer-mask" @click.self="closeViewer"><div class="look-viewer" role="dialog" aria-modal="true" :aria-label="viewer.title"><header><strong>{{viewer.title}}</strong><button class="btn btn-sm btn-ghost" aria-label="关闭大图" @click="closeViewer">✕</button></header><img :src="viewer.src" :alt="viewer.title"></div></div></Teleport>

    <div v-if="designing" class="modal-mask" @click.self="designing=false"><form class="modal card design-modal" @submit.prevent="designOutfit"><h2>基于角色标准像设计新形象</h2><p class="sub">角色标准像负责锁定同一张脸和项目画风。你只需描述整体造型，AI会设计服装、鞋履、发型和必要配饰；审核后生成套装图时，会以标准像为第一参考图完成换衣。</p><label>形象名称（可选）<input v-model="designForm.name" class="input" placeholder="例如：雨夜潜行造型"></label><label>年龄阶段<select v-model.number="designForm.age_stage_id" class="input"><option :value="0">主形象（沿用角色主标准像）</option><option v-for="s in stages" :key="s.id" :value="s.id">{{ageStageLabel(s)}} · {{s.audit_status}}</option></select></label><div v-if="designForm.age_stage_id" class="field-hint">该套装按所选阶段的外貌设计；生成换装定妆照时以阶段标准像锁定身份，不使用成人四视图。</div><label>换装定妆照引擎<select v-model="designForm.image_engine" class="input"><option value="krea2">Krea2</option><option value="qwen_image_2_1">Qwen-Image-2.1（多图编辑）</option></select></label><div class="field-hint">Krea2 适合现有流程；Qwen-Image-2.1 会按顺序使用标准像、四视图及已生成的造型资产参考图。</div><label>新形象概念<textarea v-model="designForm.concept" class="textarea" rows="7" required placeholder="例如：为现代都市女记者设计雨夜调查形象，深灰防水风衣，便于行动但保持专业感，短发做湿发收束，低跟防滑短靴，只使用银色小耳钉，不要武器和剧情道具。"></textarea></label><label><input v-model="designForm.is_default" type="checkbox"> 设为默认套装</label><div v-if="designError" class="notice error-notice design-error">{{designError}}</div><div class="field-hint">流程：标准像锁定身份 → AI拆分造型资产 → 人工审核 → 以标准像换衣生成完整套装图 → 生成四视图。不会修改或覆盖原标准像。</div><div class="actions"><button type="button" class="btn btn-ghost" @click="designing=false">取消</button><button class="btn" :disabled="designBusy||!designForm.concept.trim()">{{designBusy?'AI设计中…':'生成新形象草稿'}}</button></div></form></div>

    <div v-if="editingLook" class="modal-mask" @click.self="editingLook=null"><form class="modal card" @submit.prevent="saveLook"><h2>{{lookForm.id?'编辑':'新建'}}独立资产</h2><label>名称<input v-model="lookForm.name" class="input" required></label><label>分类<select v-model="lookForm.category" class="input"><option v-for="(v,k) in labels" :key="k" :value="k">{{v}}</option></select></label><label>描述<textarea v-model="lookForm.description" class="textarea" rows="5"></textarea></label><button type="button" class="btn btn-secondary" :disabled="expanding||!lookForm.name||!lookForm.description" @click="expandDraft">{{expanding?'AI扩写中…':'✨ AI扩写并生成提示词'}}</button><label>参考图提示词<textarea v-model="lookForm.prompt" class="textarea" rows="4"></textarea></label><label>优先级<input v-model.number="lookForm.priority" type="number" min="0" max="100" class="input"></label><div class="actions"><button type="button" class="btn btn-ghost" @click="editingLook=null">取消</button><button class="btn">保存</button></div></form></div>

    <div v-if="editingOutfit" class="modal-mask" @click.self="editingOutfit=null"><form class="modal card outfit-modal" @submit.prevent="saveOutfit"><h2>{{outfitForm.id?'编辑':'新建'}}完整套装</h2><label>套装名称<input v-model="outfitForm.name" class="input" placeholder="例如：日常工作造型" required></label><label>换装定妆照引擎<select v-model="outfitForm.image_engine" class="input"><option value="krea2">Krea2</option><option value="qwen_image_2_1">Qwen-Image-2.1（多图编辑）</option></select></label><label>年龄阶段<select v-model.number="outfitForm.age_stage_id" class="input"><option :value="0">主形象（沿用角色主标准像）</option><option v-for="s in stages" :key="s.id" :value="s.id">{{ageStageLabel(s)}} · {{s.audit_status}}</option></select></label><label>套装说明<textarea v-model="outfitForm.description" class="textarea" rows="3" placeholder="适用场景、整体气质"></textarea></label><label><input v-model="outfitForm.is_default" type="checkbox"> 设为默认套装</label><div v-for="(label,cat) in labels" :key="cat" class="asset-pick"><strong>{{label}}</strong><label v-for="x in looks.filter(v=>v.category===cat)" :key="x.id"><input v-model="outfitForm.look_ids" type="checkbox" :value="x.id"> {{x.name}} <small>({{x.audit_status}})</small></label><span v-if="!looks.some(v=>v.category===cat)" class="field-hint">暂无{{label}}资产</span></div><div class="actions"><button type="button" class="btn btn-ghost" @click="editingOutfit=null">取消</button><button class="btn">保存套装</button></div></form></div>

    <div v-if="editingStage" class="modal-mask" @click.self="editingStage=false"><form class="modal card" @submit.prevent="saveStage"><h2>{{stageForm.id?'编辑':'新建'}}年龄阶段</h2><label>阶段名称<input v-model="stageForm.name" class="input" required placeholder="例如：童年"></label><label>年龄（可选）<input v-model.number="stageForm.age" type="number" min="0" max="150" class="input" placeholder="例如：6"></label><label>该年龄的人物形象<textarea v-model="stageForm.appearance" class="textarea" rows="6" required placeholder="例如：6岁女孩，圆脸，齐刘海短发，身形瘦小，眼睛明亮。可只写几句要点，再点「AI扩写」补全脸型、发型、体态与基础服饰。"></textarea></label><div class="stage-expand"><button type="button" class="btn btn-sm btn-secondary" :disabled="stageExpanding||!stageForm.appearance?.trim()" @click="expandStageAppearance">{{stageExpanding?'AI扩写中…':'AI扩写'}}</button><button v-if="stageAppearanceBefore!==null" type="button" class="btn btn-sm btn-ghost" @click="stageForm.appearance=stageAppearanceBefore;stageAppearanceBefore=null">撤销扩写</button><span class="field-hint">按你写的内容、用项目的人物形象 Skill 扩写，你写明的部分会保留；结果只填入上面的文本框，保存前可继续修改。<template v-if="stageExpandSkill">本次使用 Skill：{{stageExpandSkill}}</template></span></div><label>四视图引擎<select v-model="stageForm.portrait_engine" class="input"><option v-for="e in ageStagePortraitEngines" :key="e.value" :value="e.value">{{e.label}}</option></select></label><div class="field-hint">每个年龄单独追加一个阶段（例如「童年 6岁」「少年 15岁」），各自保存四视图与提示词，互不覆盖，也不会改动角色主标准像和主四视图。阶段四视图以角色主标准像为参考，只延续脸部特征与画风；年龄、体型、发型和服装按这里的描述。<template v-if="stageForm.id">这里是编辑已有阶段：要新增一个年龄请返回点「新建年龄阶段」，不要在这里改年龄。修改外貌、年龄或来源会把该阶段退回草稿；已选用该阶段套装的 Scene 会标记提示词需更新。</template><template v-else>保存后会直接打开提示词审阅，可先只保存提示词，稍后再生成。</template></div><div v-if="stageError" class="notice error-notice design-error">{{stageError}}</div><div class="actions"><button type="button" class="btn btn-ghost" @click="editingStage=false">取消</button><button class="btn" :disabled="stageBusy">保存阶段</button></div></form></div>

    <div v-if="stagePrompt" class="modal-mask" @click.self="stagePrompt=null"><form class="modal card design-modal" @submit.prevent="generateStagePortrait"><h2>阶段四视图 · {{ageStageLabel(stagePrompt.stage)}}</h2><p class="sub">{{stagePromptHint(stagePrompt.stage)}}</p><label>提示词（可人工修改，提交前不会被改写）<textarea v-model="stagePrompt.text" class="textarea" rows="10" required></textarea></label><div v-if="stageError" class="notice error-notice design-error">{{stageError}}</div><div class="actions"><button type="button" class="btn btn-ghost" :disabled="stagePrompt.text===stagePrompt.draft" @click="stagePrompt.text=stagePrompt.draft">恢复系统草稿</button><button type="button" class="btn btn-ghost" @click="stagePrompt=null">取消</button><button type="button" class="btn btn-secondary" :disabled="stageBusy||!stagePrompt.text.trim()" @click="saveStagePrompt">只保存提示词</button><button class="btn" :disabled="stageBusy||!stagePrompt.text.trim()">{{stageBusy?'提交中…':'保存并提交生成'}}</button></div></form></div>

    <div v-if="outfitHistory" class="modal-mask" @click.self="outfitHistory=null"><div class="modal card outfit-modal"><h2>历史版本 · {{outfitHistory.outfit.name}}</h2><p class="sub">重新生成、手工替换或修改套装时，旧的定妆照和四视图都会保留在这里，不自动清理。「设为当前」后，使用该套装的 Scene 会标记提示词需更新，已生成的媒体保留。</p><p v-if="outfitHistory.error" class="error-text">{{outfitHistory.error}}</p><div v-if="outfitHistory.busy" class="field-hint">加载中…</div><template v-else v-for="group in outfitHistoryGroups" :key="group.type"><h3>{{group.label}}（{{group.rows.length}}）</h3><div v-if="!group.rows.length" class="field-hint">暂无历史版本。</div><div class="history-grid"><figure v-for="v in group.rows" :key="v.id"><img :src="img(v.file)" :alt="`${outfitHistory.outfit.name}${group.label}`" title="点击查看大图" @click="openViewer(v.file, `${outfitHistory.outfit.name} · ${group.label}`)"><span v-if="v.file===outfitHistory.outfit[group.field]" class="badge">当前</span><button v-else class="btn btn-xs btn-secondary" @click="selectOutfitVariant(v)">设为当前</button></figure></div></template><div class="modal-actions"><button class="btn btn-ghost" @click="outfitHistory=null">关闭</button></div></div></div>
<div v-if="episodeAssign" class="modal-mask" @click.self="episodeAssign=null"><div class="modal card outfit-modal episode-modal"><h2>按集指定 · {{episodeAssign.outfit.name}}</h2><p class="sub">只作用于每集最新版本、未归档、且「{{character?.name}}」在画面中可见（含已确认别名）的 Scene。先预览，确认后才写入；已生成的图片/视频保留，不会自动重新生成。</p><div class="episode-range"><label>从第<input v-model.number="episodeForm.from" type="number" min="1" class="input">集</label><label>到第<input v-model.number="episodeForm.to" type="number" min="1" class="input">集</label><button type="button" class="btn btn-secondary" :disabled="episodeBusy||!validEpisodeRange(episodeForm.from,episodeForm.to)" @click="previewEpisodes">预览受影响 Scene</button></div><label class="inline-check"><input v-model="episodeForm.overwrite" type="checkbox"> 覆盖已手动选择的其他套装（默认跳过）</label><div v-if="episodeError" class="notice error-notice design-error">{{episodeError}}</div><template v-if="episodeAssign.preview"><div class="notice">{{episodeAssign.applied?`已应用：修改 ${episodeAssign.preview.assign} 个 Scene，这些 Scene 已标记提示词需更新。`:episodeAssignSummary(episodeAssign.preview)}}</div><div v-if="!episodeAssign.preview.items.length" class="field-hint">该范围内没有「{{character?.name}}」可见的 Scene。</div><table v-else class="episode-table"><thead><tr><th>集</th><th>Scene</th><th>当前套装</th><th>处理</th></tr></thead><tbody><tr v-for="x in episodeAssign.preview.items" :key="x.scene_id" :class="x.action"><td>第{{x.episode_n}}集</td><td>#{{x.order}} {{x.title||'未命名'}}<small v-if="x.has_media"> · 已有媒体</small></td><td>{{x.current_outfit_name||'未选择'}}</td><td>{{episodeAssignActionLabels[x.action]||x.action}}</td></tr></tbody></table></template><div class="actions"><button type="button" class="btn btn-ghost" @click="episodeAssign=null">{{episodeAssign.applied?'关闭':'取消'}}</button><button v-if="!episodeAssign.applied" class="btn" :disabled="episodeBusy||!episodeAssign.preview?.assign" @click="applyEpisodes">{{episodeBusy?'处理中…':'确认应用到这些 Scene'}}</button></div></div></div>
  </div>
</template>
<script setup>
import{computed,onMounted,onUnmounted,reactive,ref,watch}from'vue';import{useRoute}from'vue-router';import{ageStagePortraitEngines,normalizeStageEngine,stageReferenceToken,ageStageLabel,stageApproved,validEpisodeRange,episodeAssignSummary,episodeAssignActionLabels}from'../utils/characterAgeStage.js';
const r=useRoute(),pid=r.params.id,cid=r.params.cid,character=ref(null),looks=ref([]),outfits=ref([]),motions=ref([]),stages=ref([]),editingStage=ref(false),stageForm=reactive({}),stagePrompt=ref(null),outfitHistory=ref(null),stageBusy=ref(false),stageError=ref(''),stageExpanding=ref(false),stageAppearanceBefore=ref(null),stageExpandSkill=ref(''),episodeAssign=ref(null),episodeForm=reactive({from:1,to:1,overwrite:false}),episodeBusy=ref(false),episodeError=ref(''),mode=ref(['assets','outfits','motion','stages'].includes(String(r.query.mode))?String(r.query.mode):'outfits'),activeCategory=ref('clothing'),editingLook=ref(null),editingOutfit=ref(null),designing=ref(false),designBusy=ref(false),designError=ref(''),viewer=ref(null),error=ref(''),expanding=ref(false),motionName=ref(''),motionVideo=ref(null),motionAudio=ref(null),motionUploading=ref(false),lookForm=reactive({}),outfitForm=reactive({}),designForm=reactive({name:'',concept:'',image_engine:'krea2',is_default:false,age_stage_id:0});let timer;
const openViewer=(name,title)=>{if(name)viewer.value={src:img(name),title}};const closeViewer=()=>{viewer.value=null};
const imageEngineLabel=value=>value==='qwen_image_2_1'?'Qwen-Image-2.1':'Krea2';const labels={clothing:'服装',shoes:'鞋履',hair:'发型',hair_accessory:'发饰',jewelry:'首饰',bag:'包'};const filteredLooks=computed(()=>looks.value.filter(x=>x.category===activeCategory.value));const img=n=>`/api/input/${pid}/${n}`;const approved=o=>o.audit_status==='approved'||o.audit_status==='published';
async function request(url,opt={}){const res=await fetch(url,opt);if(!res.ok){let m='请求失败';try{m=(await res.json()).error||m}catch{}throw new Error(m)}return res.status===204?null:res.json()}
async function load(){try{const [characterPayload,lookRows,outfitRows,motionRows,stageRows]=await Promise.all([request(`/api/projects/${pid}/characters`),request(`/api/projects/${pid}/characters/${cid}/looks`),request(`/api/projects/${pid}/characters/${cid}/outfits`),request(`/api/projects/${pid}/characters/${cid}/motion-references`),request(`/api/projects/${pid}/characters/${cid}/age-stages`)]);stages.value=Array.isArray(stageRows)?stageRows:[];const characters=Array.isArray(characterPayload)?characterPayload:(Array.isArray(characterPayload?.characters)?characterPayload.characters:[]);character.value=characters.find(x=>String(x.id)===String(cid))||null;if(!character.value)throw new Error('当前角色不存在或不属于该项目');looks.value=Array.isArray(lookRows)?lookRows:[];outfits.value=Array.isArray(outfitRows)?outfitRows:[];motions.value=Array.isArray(motionRows)?motionRows:[]}catch(e){error.value=e.message}}
function openDesign(stage){if(!character.value?.portrait){error.value='请先为当前角色生成或上传标准像';return}Object.assign(designForm,{name:'',concept:'',image_engine:'krea2',is_default:false,age_stage_id:stage?.id||0});designError.value='';designing.value=true}
async function designOutfit(){designBusy.value=true;designError.value='';error.value='';try{await request(`/api/projects/${pid}/characters/${cid}/outfits/design`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(designForm)});designing.value=false;mode.value='outfits';await load()}catch(e){designError.value=e.message}finally{designBusy.value=false}}
function openLook(x){Object.assign(lookForm,x||{id:0,name:'',category:'clothing',description:'',prompt:'',priority:50});editingLook.value=true}function derive(x){Object.assign(lookForm,{id:0,name:x.name+'变体',category:x.category,description:x.description,prompt:x.prompt,priority:x.priority});editingLook.value=true}
async function expandDraft(){expanding.value=true;try{const d=await request(`/api/projects/${pid}/characters/${cid}/looks/expand-preview`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(lookForm)});lookForm.description=d.description;lookForm.prompt=d.prompt}catch(e){error.value=e.message}finally{expanding.value=false}}
async function saveLook(){const u=`/api/projects/${pid}/characters/${cid}/looks${lookForm.id?'/'+lookForm.id:''}`;await request(u,{method:lookForm.id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(lookForm)});editingLook.value=null;load()}
async function actLook(x,a){try{await request(`/api/projects/${pid}/characters/${cid}/looks/${x.id}/${a}`,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});load()}catch(e){error.value=e.message}}
async function upload(x,e){const f=e.target.files?.[0];if(!f)return;const fd=new FormData();fd.append('file',f);try{await request(`/api/projects/${pid}/characters/${cid}/looks/${x.id}/image/upload`,{method:'POST',body:fd});load()}catch(er){error.value=er.message}}
async function removeLook(x){if(confirm(`删除资产“${x.name}”？`)){await request(`/api/projects/${pid}/characters/${cid}/looks/${x.id}`,{method:'DELETE'});load()}}
function openOutfit(o){Object.assign(outfitForm,{id:o?.id||0,age_stage_id:o?.age_stage_id||0,name:o?.name||'',description:o?.description||'',image_engine:o?.image_engine||'krea2',is_default:!!o?.is_default,look_ids:o?.items?.map(i=>i.look_id)||[]});editingOutfit.value=true}
async function saveOutfit(){const u=`/api/projects/${pid}/characters/${cid}/outfits${outfitForm.id?'/'+outfitForm.id:''}`;await request(u,{method:outfitForm.id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(outfitForm)});editingOutfit.value=null;load()}
async function outfitAct(o,a){try{await request(`/api/projects/${pid}/characters/${cid}/outfits/${o.id}/${a}`,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});load()}catch(e){error.value=e.message}}
async function uploadOutfit(o,e,sheet){const f=e.target.files?.[0];if(!f)return;const fd=new FormData();fd.append('file',f);try{await request(`/api/projects/${pid}/characters/${cid}/outfits/${o.id}/image/upload${sheet?'?kind=sheet':''}`,{method:'POST',body:fd});load()}catch(er){error.value=er.message}}
async function removeOutfit(o){if(confirm(`删除套装“${o.name}”？`)){await request(`/api/projects/${pid}/characters/${cid}/outfits/${o.id}`,{method:'DELETE'});load()}}
const stagePromptHint=s=>`使用 ${stageEngineLabel(s?.portrait_engine)}，以角色主标准像为参考、按 Moss 四视图结构生成：正面面部特写、正面全身、侧面全身、背面全身。参考图只锁定脸部特征与画风，年龄以阶段描述为准；提示词须保留 ${stageReferenceToken(s?.portrait_engine)}。`;const stageEngineLabel=v=>ageStagePortraitEngines.find(e=>e.value===normalizeStageEngine(v))?.label||v;const stageBlocked=o=>!!o.age_stage_id&&!(stageApproved(o.age_stage)&&o.age_stage?.portrait);const stageURL=s=>`/api/projects/${pid}/characters/${cid}/age-stages${s?.id?'/'+s.id:''}`;const jsonOpt=(method,body)=>({method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
function openStage(s){Object.assign(stageForm,{id:s?.id||0,name:s?.name||'',age:s?.age??'',appearance:s?.appearance||'',portrait_engine:normalizeStageEngine(s?.portrait_engine)});stageError.value='';stageAppearanceBefore.value=null;editingStage.value=true}
async function expandStageAppearance(){stageExpanding.value=true;stageError.value='';try{const age=Number.isInteger(stageForm.age)?stageForm.age:null;const before=stageForm.appearance;const d=await request(`${stageURL()}/expand-appearance`,jsonOpt('POST',{name:stageForm.name?.trim()||'',age,brief:before.trim()}));if(d?.appearance){stageAppearanceBefore.value=before;stageForm.appearance=d.appearance;stageExpandSkill.value=d.skill||''}}catch(e){stageError.value=e.message}finally{stageExpanding.value=false}}
async function saveStage(){stageBusy.value=true;stageError.value='';try{const age=Number.isInteger(stageForm.age)?stageForm.age:null;const created=!stageForm.id;const row=await request(stageURL(stageForm),jsonOpt(stageForm.id?'PUT':'POST',{name:stageForm.name.trim(),age,appearance:stageForm.appearance.trim(),portrait_engine:stageForm.portrait_engine}));editingStage.value=false;mode.value='stages';await load();if(created&&row?.id)await openStagePrompt(row)}catch(e){stageError.value=e.message}finally{stageBusy.value=false}}
async function openStagePrompt(s){error.value='';stageError.value='';try{const d=await request(`${stageURL(s)}/portrait/prompt`);stagePrompt.value={stage:s,text:d.saved_prompt||d.draft_prompt||'',draft:d.draft_prompt||''}}catch(e){error.value=e.message}}
async function generateStagePortrait(){stageBusy.value=true;stageError.value='';try{await request(`${stageURL(stagePrompt.value.stage)}/portrait`,jsonOpt('POST',{prompt:stagePrompt.value.text}));stagePrompt.value=null;await load()}catch(e){stageError.value=e.message}finally{stageBusy.value=false}}
const outfitHistoryGroups=computed(()=>{const h=outfitHistory.value;if(!h)return[];return[{type:'character_outfit_image',field:'image',label:'换装定妆照'},{type:'character_outfit_sheet',field:'sheet',label:'四视图'}].map(g=>({...g,rows:h.rows[g.type]||[]}))});
async function loadOutfitHistory(){const h=outfitHistory.value;if(!h)return;h.busy=true;h.error='';try{const types=['character_outfit_image','character_outfit_sheet'];const lists=await Promise.all(types.map(t=>request(`/api/projects/${pid}/asset-variants?entity_type=${t}&entity_id=${h.outfit.id}`)));h.rows=Object.fromEntries(types.map((t,i)=>[t,lists[i]?.variants||[]]))}catch(e){h.error=e.message}finally{h.busy=false}}
async function openOutfitHistory(o){outfitHistory.value={outfit:o,rows:{},busy:false,error:''};await loadOutfitHistory()}
async function selectOutfitVariant(v){if(!confirm('把这张历史图设为当前？当前这张会保留在历史里。'))return;try{await request(`/api/projects/${pid}/asset-variants/${v.id}/select`,{method:'POST'});await load();const fresh=outfits.value.find(x=>x.id===outfitHistory.value?.outfit.id);if(fresh)outfitHistory.value.outfit=fresh;await loadOutfitHistory()}catch(e){outfitHistory.value.error=e.message}}
const stageHistory=s=>{try{const v=JSON.parse(s?.portrait_history||'[]');return Array.isArray(v)?v.filter(Boolean):[]}catch{return[]}};
async function saveStagePrompt(){stageBusy.value=true;stageError.value='';try{await request(`${stageURL(stagePrompt.value.stage)}/portrait/prompt`,jsonOpt('PUT',{prompt:stagePrompt.value.text}));stagePrompt.value=null;await load()}catch(e){stageError.value=e.message}finally{stageBusy.value=false}}
async function restoreStagePortrait(s,file){if(!confirm(`把这张历史四视图恢复为「${ageStageLabel(s)}」的当前四视图？当前这张会进入历史，不会删除。`))return;try{await request(`${stageURL(s)}/portrait/restore`,jsonOpt('POST',{file}));await load()}catch(e){error.value=e.message}}
async function uploadStage(s,e){const f=e.target.files?.[0];if(!f)return;const fd=new FormData();fd.append('file',f);try{await request(`${stageURL(s)}/portrait/upload`,{method:'POST',body:fd});await load()}catch(er){error.value=er.message}}
async function approveStage(s){try{await request(`${stageURL(s)}/approve`,jsonOpt('POST',{}));await load()}catch(e){error.value=e.message}}
async function removeStage(s){if(!confirm(`删除年龄阶段“${ageStageLabel(s)}”？`))return;try{await request(stageURL(s),{method:'DELETE'});await load()}catch(e){error.value=e.message}}
function openEpisodeAssign(o){Object.assign(episodeForm,{from:1,to:1,overwrite:false});episodeError.value='';episodeAssign.value={outfit:o,preview:null,applied:false}}
watch(()=>[episodeForm.from,episodeForm.to,episodeForm.overwrite],()=>{if(episodeAssign.value&&!episodeAssign.value.applied)episodeAssign.value.preview=null});
const episodeBody=preview=>({from_episode:episodeForm.from,to_episode:episodeForm.to,overwrite:episodeForm.overwrite,preview});
async function previewEpisodes(){episodeBusy.value=true;episodeError.value='';try{episodeAssign.value.preview=await request(`/api/projects/${pid}/characters/${cid}/outfits/${episodeAssign.value.outfit.id}/assign-episodes`,jsonOpt('POST',{...episodeBody(false),preview:true}))}catch(e){episodeError.value=e.message}finally{episodeBusy.value=false}}
async function applyEpisodes(){episodeBusy.value=true;episodeError.value='';try{const res=await request(`/api/projects/${pid}/characters/${cid}/outfits/${episodeAssign.value.outfit.id}/assign-episodes`,jsonOpt('POST',episodeBody(false)));episodeAssign.value={...episodeAssign.value,preview:res,applied:true}}catch(e){episodeError.value=e.message}finally{episodeBusy.value=false}}
const fileURL=value=>{const p=String(value||'').replace(/\\/g,'/').replace(/^\/+/, '');const i=p.indexOf('/');return i>0?`/api/input/${p.slice(0,i)}/${p.slice(i+1)}`:`/api/input/${pid}/${p}`}
async function uploadMotion(){const video=motionVideo.value?.files?.[0];if(!video)return;motionUploading.value=true;const fd=new FormData();fd.append('video',video);const audio=motionAudio.value?.files?.[0];if(audio)fd.append('audio',audio);if(motionName.value)fd.append('name',motionName.value);try{await request(`/api/projects/${pid}/characters/${cid}/motion-references`,{method:'POST',body:fd});motionName.value='';motionVideo.value.value='';if(motionAudio.value)motionAudio.value.value='';await load()}catch(e){error.value=e.message}finally{motionUploading.value=false}}
async function selectMotion(m){try{await request(`/api/projects/${pid}/characters/${cid}/motion-references/${m.id}/select`,{method:'POST'});await load()}catch(e){error.value=e.message}}
async function deleteMotion(m){if(!confirm(`删除动态参考“${m.name}”？`))return;try{await request(`/api/projects/${pid}/characters/${cid}/motion-references/${m.id}`,{method:'DELETE'});await load()}catch(e){error.value=e.message}}
function onViewerKey(event){if(event.key==='Escape'&&viewer.value)closeViewer()}
onMounted(async()=>{window.addEventListener('keydown',onViewerKey);await load();if(r.query.design==='1')openDesign();else if(r.query.new==='1'&&mode.value==='assets')openLook();else if(r.query.new==='1'&&mode.value==='stages')openStage();timer=setInterval(load,3000)});onUnmounted(()=>{window.removeEventListener('keydown',onViewerKey);clearInterval(timer)});
</script>
